target.css:
:root {
  --ink: #25352b;
  --muted: #6f7f70;
  --paper: #fffdf6;
  --line: #d9dfd2;
  --moss: #526f4e;
  --pale-moss: #e8efe2;
  --clay: #bb684d;
  --clay-dark: #914b38;
}

.bonsai-board {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.board-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.eyebrow {
  margin: 0;
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.title-block h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -0.5px;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--pale-moss);
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.work-grid {
  display: grid;
  grid-template-columns: 142px 1fr;
  gap: 14px;
  padding: 14px 0;
}

.tree-figure {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  min-height: 142px;
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--pale-moss);
  text-align: center;
}

.tree-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  margin-bottom: 9px;
  border-radius: 50%;
  background: var(--moss);
  font-size: 27px;
}

.tree-figure figcaption {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

.tree-figure figcaption strong {
  color: var(--ink);
  font-size: 12px;
}

.details {
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  border-radius: 9px;
  background: var(--pale-moss);
}

.metric span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.metric strong {
  color: var(--ink);
  font-size: 11px;
  line-height: 1.15;
}

.tasks {
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.task-heading {
  display: flex;
  justify-content: space-between;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.task-heading strong {
  color: var(--clay-dark);
  letter-spacing: 0;
}

.task-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 8px;
  margin: 7px 0 0;
  padding: 0;
  list-style: none;
  color: var(--ink);
  font-size: 11px;
  line-height: 1.2;
}

.task-list li {
  display: flex;
  align-items: center;
  gap: 5px;
}

.check {
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--moss);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
}

.check.pending {
  background: var(--clay);
  font-size: 14px;
  line-height: 1;
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.session-note {
  color: var(--muted);
  font-size: 11px;
}

.board-footer button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--clay);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

